import type { JSX, ValidComponent } from "@solidjs/web";
import { REASONS } from "../../internals/change-event-details.js";
import { type BaseUIChangeEventDetails } from "../../internals/change-event-details.js";
import { type MaybeAccessor } from "../../internals/maybe-accessor.js";
import type { BaseUIComponentProps } from "../../internals/types.js";
import { type AccordionItemState } from "../accordion-item-context.js";
export type { AccordionItemState };
export type AccordionItemChangeEventReason = typeof REASONS.triggerPress | typeof REASONS.none;
export type AccordionItemChangeEventDetails = BaseUIChangeEventDetails<AccordionItemChangeEventReason>;
export interface AccordionItemProps extends BaseUIComponentProps<"div", AccordionItemState> {
    /** Tag/component to render. Defaults to `"div"`. */
    as?: ValidComponent;
    /**
     * A unique value that identifies this item. If omitted, an auto-generated
     * id is used — pass an explicit value when controlling which item is
     * open, or for stable SSR markup.
     */
    value?: unknown;
    /** Whether this item ignores user interaction. */
    disabled?: MaybeAccessor<boolean | undefined>;
    /**
     * Fired when the item's panel opens or closes. The second argument is the
     * cancel-capable details bag.
     */
    onOpenChange?: ((open: boolean, eventDetails: AccordionItemChangeEventDetails) => void) | undefined;
}
/**
 * Groups an accordion header with its panel. Renders a `<div>` element.
 *
 * Solid 2 notes:
 *
 * - Each item composes an internal `createCollapsible` (axis B controlled
 *   embedding pattern, validated in spike 01a). Open state is owned by
 *   the root — `createCollapsible` runs in MaybeAccessor-controlled mode
 *   via `open: isOpen`. The `onOpenChange` adapter bridges the
 *   primitive's new `(next, event)` shape to the public
 *   `(next, details)` shape the AccordionItem API has shipped with, and
 *   forwards non-canceled changes to `root.handleValueChange`.
 * - The single `c.Provider` exposes the api context consumed by
 *   `<Accordion.Trigger>` / `<Accordion.Panel>` (via `useCollapsible()`)
 *   and any descendant calling the primitive directly. The legacy
 *   `CollapsibleRootContext` bridge was removed in the AccordionPanel
 *   migration (stage-01c cleanup chain).
 * - The item registers with the root's `<CompositeList>` so the trigger
 *   can enumerate sibling items for keyboard navigation.
 *
 * **Cancellation bridge subtlety:** the public AccordionItem callback
 * fires with `(next, details)` and the consumer can call
 * `details.cancel()`. The bridge translates that to
 * `event.preventDefault()` on the primitive's event so the primitive's
 * internal write is also vetoed. Both cancel styles work.
 */
export declare function AccordionItem(props: AccordionItemProps): JSX.Element;
```

