import type { JSX, ValidComponent } from "@solidjs/web";
import type { BaseUIComponentProps } from "../../internals/types.js";
import { type AccordionItemState } from "../accordion-item-context.js";
export interface AccordionPanelState extends AccordionItemState {
}
export interface AccordionPanelProps extends BaseUIComponentProps<"div", AccordionPanelState> {
    /** Tag/component to render. Defaults to `"div"`. */
    as?: ValidComponent;
    /**
     * When `true`, the browser's built-in page search can find and expand
     * closed panel contents via `hidden="until-found"`. Forces the panel to
     * stay mounted. Overrides the root's `hiddenUntilFound`.
     * @default false
     */
    hiddenUntilFound?: boolean | undefined;
    /**
     * Whether to keep the element in the DOM while the panel is hidden.
     * Ignored when {@link hiddenUntilFound} is `true`. Overrides the root's
     * `keepMounted`.
     * @default false
     */
    keepMounted?: boolean | undefined;
}
/**
 * Collapsible panel with the accordion item's contents. Renders a `<div
 * role="region">` element.
 *
 * Solid 2 notes:
 *
 * - The panel reads the collapsible API via `useCollapsible()` (provided by
 *   `AccordionItem`'s `c.Provider`) and composes `createMountTransition`
 *   directly — same shape as `<Collapsible.Panel>`. This lets us merge in
 *   accordion-specific attrs (`aria-labelledby`, `role="region"`, the index
 *   projection) without double-wrapping.
 * - `aria-labelledby` is seeded with `""` — see the trigger for the
 *   `merge-props-undefined-attr.test.tsx` rationale.
 * - Panel-level `hiddenUntilFound` and `keepMounted` fall back to the root's
 *   values when unset — matches React's `hiddenUntilFoundProp ?? contextHiddenUntilFound`.
 * - `m.shouldRender()` follows `mounted || keepMounted || hiddenUntilFound`.
 *   Once the exit animation finishes and `mounted` flips false, the panel
 *   unmounts unless the consumer opted into keep-mounted.
 */
export declare function AccordionPanel(props: AccordionPanelProps): JSX.Element;
```

