import type { JSX, ValidComponent } from "@solidjs/web";
import type { BaseUIComponentProps, NativeButtonProps } from "../../internals/types.js";
import { type AccordionItemState } from "../accordion-item-context.js";
export interface AccordionTriggerState extends AccordionItemState {
}
export interface AccordionTriggerProps extends NativeButtonProps, BaseUIComponentProps<"button", AccordionTriggerState> {
    /** Tag/component to render. Defaults to `"button"`. */
    as?: ValidComponent;
}
/**
 * Button that expands or collapses its item's panel. Renders a `<button>` by
 * default; use `nativeButton={false}` with a `render` prop override to render
 * a non-button element.
 *
 * Solid 2 notes:
 *
 * - The keyboard handler walks `root.accordionItemRefs` (a plain array kept
 *   in DOM order by `<CompositeList>`) and builds a "live" list of sibling
 *   triggers on every key press. This matches React's approach — no
 *   pre-computed ref tracking, so re-ordering is handled naturally.
 * - `aria-controls` is gated on `open` (matching React) — the getter returns
 *   `undefined` while closed so the attribute is omitted (not `aria-controls=""`
 *   pointing at a non-existent panel). `id` uses a `""` seed so the key stays
 *   in `ownKeys` from the first spread. `mergeRootProps` declares every getter
 *   key as `own` regardless of value, so a getter starting `undefined` still
 *   tracks (see `test/internals/merge-props-undefined-attr.test.tsx`).
 * - `aria-expanded` emits the literal `"true"`/`"false"` string — RFC 07's
 *   enumerated-pseudo-boolean rules collapse raw `true` to a presence
 *   attribute, which breaks AT that keys off the literal string.
 * - The consumer-supplied `id` registers as the item's `triggerId` so the
 *   panel's `aria-labelledby` can point to it. We also use it as the
 *   trigger's own `id` (so the trigger and panel form a two-way ARIA link).
 *   Registration happens in a `createRenderEffect` and is cleaned up on
 *   unmount — matches React's `useIsoLayoutEffect`.
 */
export declare function AccordionTrigger(props: AccordionTriggerProps): JSX.Element;
```


