     * (handle was constructed but never used inside a live `<Dialog.Root>`),
     * this is a no-op.
     */
    setOpen(next: boolean, details: DialogRootChangeEventDetails): void;
    /** Imperative payload writer. No-op when no root is bound. */
    setPayload(payload: _Payload | undefined): void;
