}
/**
 * `DialogHandle` — imperative + cross-tree trigger-association surface.
 *
 * Matches Base UI React's `DialogHandle` on the public method surface
 * (`open(triggerId)` / `openWithPayload(payload)` / `close()` / `isOpen`)
 * and carries an internal store that `<Dialog.Root handle={...}>` adopts.
 *
 * Usage:
 *
 * ```ts
 * const handle = Dialog.createHandle<MyPayload>();
 *
 * // ... inside the component
 * <Dialog.Root handle={handle}>
 *   <Dialog.Trigger id="t1" handle={handle}>Open</Dialog.Trigger>
 *   {/* ... *\/}
