import { type Accessor } from "solid-js";
/**
 * Image-loading status reported by `<Avatar.Image>` into the root context so
 * that `<Avatar.Fallback>` can decide whether to render.
 *
 * - `idle`     — no image mounted yet (or src is absent)
 * - `loading`  — a real image has been attached and is fetching
 * - `loaded`   — the image's `onload` fired; the image is visible
 * - `error`    — the image's `onerror` fired (or src was empty)
 */
