export interface AvatarRootContextValue {
    /** Reactive accessor for the current image-loading status. */
    imageLoadingStatus: Accessor<ImageLoadingStatus>;
    /** Setter invoked by `<Avatar.Image>` on each load/error transition. */
    setImageLoadingStatus: (next: ImageLoadingStatus) => void;
}
