 * `state` is a composite accessor handed to `renderElement` for the `data-*`
 * projection; individual accessors (`checked`, `indeterminate`, …) are the
 * read surface for `<Checkbox.Indicator>` so it doesn't need to destructure
 * `state()` at the top of its body.
 */
export interface CheckboxRootContextValue {
    /** Whether the checkbox is currently ticked. */
    checked: Accessor<boolean>;
    /** Whether the checkbox is in a mixed state (neither ticked nor unticked). */
    indeterminate: Accessor<boolean>;
    /** Whether the component ignores user interaction. */
    disabled: Accessor<boolean>;
    /** Whether user interaction is blocked without disabling the control. */
    readOnly: Accessor<boolean>;
    /** Whether the checkbox must be ticked before submitting a form. */
    required: Accessor<boolean>;
    /** Composite state accessor — fed directly to `renderElement`'s projection. */
    state: Accessor<CheckboxRootState>;
