 * sourced from `disabled`, and `checked` / `indeterminate` drive the
 * checkbox-specific `data-checked` / `data-unchecked` / `data-indeterminate`
 * triplet via the custom state-attributes mapping.
 */
export interface CheckboxRootState extends FieldRootState {
    /** Whether the checkbox is currently ticked. */
    checked: boolean;
    /** Whether the component ignores user interaction. */
    disabled: boolean;
    /** Whether the user should be unable to tick/untick the checkbox. */
    readOnly: boolean;
    /** Whether the checkbox must be ticked before submitting a form. */
    required: boolean;
    /** Whether the checkbox is in a mixed state. */
    indeterminate: boolean;
}
/**
 * Checkbox root context. `createContext<T | null>(null)` + `== null` sentinel
 * — Solid 2's `useContext` throws `ContextNotFoundError` when
 * the default is `undefined`, which would shadow the intended Base UI error
 * message below.
