import { type Accessor } from "solid-js";
import type { BaseUIChangeEventDetails, BaseUIEventReasons } from "../internals/change-event-details.js";
import type { UseCheckboxGroupParentReturnValue } from "./use-checkbox-group-parent.js";
/**
 * Change-event details handed to `setValue` by child checkboxes / the
 * parent-indicator helper. Mirrors
 * `CheckboxGroup.ChangeEventDetails` from the React port.
 */
export type CheckboxGroupChangeEventDetails = BaseUIChangeEventDetails<BaseUIEventReasons["none"]>;
/**
 * The value handed down by `<CheckboxGroup>` to its descendant
 * `<Checkbox.Root>` elements.
 *
 * Solid 2 adaptations from Base UI React's `CheckboxGroupContext`:
 *
 * - Every reactive slot is an `Accessor<T>` so child checkboxes pull on
 *   demand without tripping the top-level-reactive-read rule (RFC 01).
 * - `setValue` is wrapped in `createStableCallback` by the group root so
 *   children can capture it into closures / refs without re-wiring.
 * - `parent` carries the `useCheckboxGroupParent` return value. Its own
 *   callbacks are stable too (wrapped inside the helper).
 * - `present` is true when a real `<CheckboxGroup>` is an ancestor; child
 *   checkboxes branch on it to decide whether to override their internal
 *   `checked`/`onClick` behaviour.
 */
export interface CheckboxGroupContextValue {
    /** Current group value. */
    value: Accessor<readonly string[] | undefined>;
    /**
     * The group's `defaultValue` while the group is uncontrolled,
     * `undefined` while controlled (mirrors React Base UI's
     * `CheckboxGroupContext.defaultValue`). Child checkboxes use it to seed
     * their own uncontrolled state (`defaultGroupValue.includes(value)`).
     */
    defaultValue: Accessor<readonly string[] | undefined>;
    /** Names of all checkboxes in the group — used by the parent-indicator helper. */
    allValues: Accessor<readonly string[] | undefined>;
    /** Write to the group value. Fires `onValueChange` and respects `details.cancel()`. */
    setValue: (next: string[], details: CheckboxGroupChangeEventDetails) => void;
    /** Parent-indicator bundle (checked / indeterminate / child+parent props factories). */
    parent: UseCheckboxGroupParentReturnValue;
    /** Whether the group is disabled — propagates to every child. */
    disabled: Accessor<boolean>;
    /** Marker — `true` when provided by a real `<CheckboxGroup>`. */
    readonly present: boolean;
}
/**
 * Checkbox-group context. The default is a frozen sentinel whose `.present`
 * is false, so `useCheckboxGroupContext` can always return a safe value and
 * children branch on `present` to decide whether to override their internal
 * behaviour.
 */
export declare const CheckboxGroupContext: import("solid-js").Context<CheckboxGroupContextValue>;
/**
 * Read the surrounding `<CheckboxGroup>` context. Returns a noop (with
 * `present: false`) when no group is an ancestor — the child checkbox-root
 * branches on `.present` rather than nullishness.
 */
export declare function useCheckboxGroupContext(): CheckboxGroupContextValue;
```

