    /** Every value a child can contribute (parent-checkbox pattern). */
    allValues?: MaybeAccessor<string[] | undefined>;
    /** Whether the group should ignore user interaction. @default false */
    disabled?: MaybeAccessor<boolean | undefined>;
}
/**
 * Provides a shared value array to a series of `<Checkbox.Root>` elements.
 * Renders a `<div role="group">` (or `as` override).
 *
 * §1 wave 2: replaces `renderElement` with `dynamic(() => props.as ?? "div")`.
 * Field-validity attrs (`data-valid`/`data-invalid`/`data-touched`/`data-dirty`/
