import { type Accessor } from "solid-js";
import type { BaseUIChangeEventDetails, BaseUIEventReasons } from "../internals/change-event-details.js";
type ParentChangeEventDetails = BaseUIChangeEventDetails<BaseUIEventReasons["none"]>;
export interface UseCheckboxGroupParentParameters {
    /** All child values that participate in the parent-indicator math. */
    allValues: Accessor<readonly string[] | undefined>;
    /** Current group value (array of ticked child values). */
    value: Accessor<readonly string[] | undefined>;
    /** Group setter — invoked when the parent checkbox flips. */
    onValueChange: (next: string[], details: ParentChangeEventDetails) => void;
}
/**
 * Props the parent-checkbox consumer splats on `<Checkbox.Root parent>`. The
 * Solid port accepts them as a plain props bag (no accessors) because they're
 * consumed inside the checkbox-root's reactive scope — reads re-track on every
 * call.
 */
export interface UseCheckboxGroupParentParentProps {
    id: string;
    indeterminate: boolean;
    checked: boolean;
    "aria-controls": string;
    onCheckedChange: (checked: boolean, details: ParentChangeEventDetails) => void;
}
/**
 * Props the per-child consumer splats on each non-parent `<Checkbox.Root>`.
 */
export interface UseCheckboxGroupParentChildProps {
    checked: boolean;
    onCheckedChange: (checked: boolean, details: ParentChangeEventDetails) => void;
}
export interface UseCheckboxGroupParentReturnValue {
    /** Stable id for the parent checkbox (used by `aria-controls`). */
    id: string;
    /** Whether the parent is currently indeterminate (mixed). */
    indeterminate: Accessor<boolean>;
    /** Whether the parent is fully checked (`value.length === allValues.length`). */
    checked: Accessor<boolean>;
    /**
     * Plain mutable map of child value → disabled state. Populated by children
     * during setup so the parent's `onCheckedChange` math can skip disabled
     * entries (mirrors React's `disabledStatesRef`).
     */
    disabledStates: Map<string, boolean>;
    /** Props factory for the parent checkbox. Call inside a reactive scope. */
    getParentProps: () => UseCheckboxGroupParentParentProps;
    /** Props factory for a child checkbox keyed by its `value`. */
    getChildProps: (childValue: string) => UseCheckboxGroupParentChildProps;
}
/**
 * "Parent checkbox" helper. Matches Base UI React's `useCheckboxGroupParent`.
 *
 * The parent checkbox reflects the aggregate of its children:
 *
 * - all children checked → parent is checked
 * - no children checked  → parent is unchecked
 * - mixed               → parent is indeterminate
 *
 * Clicking the parent cycles through all-on / all-off (with an uncontrolled
 * stash so the user's mixed state can be "remembered" when cycling back).
 * Clicking a child flips just that child and resets the parent cycle back to
 * `"mixed"`.
 *
