 *
 * - `id` is generated once via `useBaseUiId`. Mirrors React's single-render
 *   id and stays stable for the component's lifetime.
 * - `indeterminate` / `checked` are derived via `createMemo` over the group
 *   value + `allValues` — no manual recomputation, no stale closures.
 * - `onValueChange` is wrapped in `createStableCallback` so the child/parent
 *   prop factories can be captured into closures without re-wiring.
 * - `disabledStates` is a plain `Map` (not a store / signal). Children push
 *   into it during setup — it's a coordination side-channel, not reactive
 *   state; the React port does the same via `disabledStatesRef`.
 * - `status` tracks the cycle phase (`"on" | "off" | "mixed"`). Declared
 *   with `ownedWrite: true` because the parent's `onCheckedChange` runs in
 *   owned scope (it's invoked from the checkbox-root's event handler chain
 *   which is itself called from inside a reactive merge proxy read — Solid
 *   doesn't mark event callbacks as unowned by default).
 * - `uncontrolledState` is a plain `let` binding (not a signal). It's a
 *   sticky last-seen "mixed" snapshot used for the cycle-back-to-mixed
 *   branch — no reactivity needed.
 */
export declare function useCheckboxGroupParent(params: UseCheckboxGroupParentParameters): UseCheckboxGroupParentReturnValue;
export {};
