}
/**
 * Shape of attributes emitted by `c.trigger()`.
 */
export interface CollapsibleTriggerSlotProps {
    type: "button";
    "aria-expanded": "true" | "false";
    "aria-controls": string | undefined;
    "data-panel-open": "" | undefined;
    "data-disabled": "" | undefined;
    onClick: (event: MouseEvent) => void;
}
export interface CollapsiblePanelSlotProps {
    id: string | undefined;
    "data-state": "open" | "closed";
    "data-open": "" | undefined;
    "data-closed": "" | undefined;
}
/**
 * Read the nearest {@link CollapsibleApi} provided by `c.Provider`.
 * Throws if used outside a Provider.
 */
export declare function useCollapsible(): CollapsibleApi;
/**
 * Solid 2.0-native compound primitive for collapsible disclosure. One call
 * owns logical state (open/disabled, panel id, change callbacks). Animation
 * lifecycle (mount, exit, measurement, beforematch) is NOT in this primitive
 * — wrappers compose `createMountTransition` over `c.open`.
 */
export declare function createCollapsible(options: CreateCollapsibleOptions): CollapsibleApi;
/**
 * Shared directive-factory pattern used by both `c.triggerRef()` /
 * `c.panelRef()` (above) and the top-level `collapsibleTrigger(c)` /
 * `collapsiblePanel(c)` exports.
 */
