import type { JSX, ValidComponent } from "@solidjs/web";
/**
 * Props for {@link CollapsiblePanel}.
 *
 * Stage-01c rewire: this wrapper is now a structural adapter over
 * `useCollapsible()` + `createMountTransition` (axes A + G + P). `render={}`
 * is gone — use `as=` to swap the underlying tag/component.
 */
export interface CollapsiblePanelProps extends JSX.HTMLAttributes<HTMLDivElement> {
    /**
     * Tag/component to render. Defaults to `"div"`. Replaces the
     * pre-spike `render` prop (axis G).
     */
    as?: ValidComponent;
    /**
     * When `true`, the browser's built-in page search can find and expand the
     * panel's contents. The panel stays in the DOM even when closed, and uses
     * `hidden="until-found"` to hide without removing.
     *
     * Overrides {@link keepMounted} (forces it to `true`).
     * @default false
     */
    hiddenUntilFound?: boolean | undefined;
    /**
     * Whether to keep the element in the DOM after the exit animation
     * completes. Ignored when {@link hiddenUntilFound} is `true`
     * (which forces it to `true`).
     *
     * **Exit animations are honored regardless of this prop** — the panel
     * always plays its CSS exit transition before either unmounting (when
     * `keepMounted={false}`) or flipping to `hidden={true}` (when
     * `keepMounted={true}`). This prop only controls what happens *after*
     * that transition finishes:
     *
     * - `false` (default) → panel unmounts; re-mounts on next open.
     * - `true` → panel stays in the DOM with `hidden={true}`.
     *
     * @default false
     */
    keepMounted?: boolean | undefined;
}
/**
 * The collapsible panel. Renders a `<div>` element (or `as` override).
 *
 * Solid 2 notes:
 *
 * - Reads the collapsible API via `useCollapsible()` — works both under
 *   `<Collapsible.Root>` and inside accordion items (both provide the new
 *   `CollapsibleContext`).
 * - `createMountTransition` owns the full animation lifecycle (mount state,
 *   enter/exit measurement, CSS vars, `beforematch` listener, `hidden` attr).
 * - The panel id is registered into `c.setPanelId()` at setup, so the trigger's
 *   `aria-controls` binding reflects the correct id.
 *
 * ### `c.panel()` shape decision — option (b)
 *
 * `c.panel()` still emits `hidden`, `style`, and `ref` (the full slot bag).
 * `m.mergePanelProps(userProps)` spreads AFTER `c.panel()`, so
 * `createMountTransition`'s `hidden`, `style`, and `ref` win on collision.
 * This keeps inline-headless working (`<div {...c.panel()}>`) without requiring
 * callers to compose `createMountTransition` separately. The cost is that
 * `c.panel()` emits keys that become unreachable when this wrapper is used —
 * those keys are dormant rather than harmful.
 *
 * Clean-up option (a) (slim `c.panel()` to drop lifecycle keys) is left for a
 * later stage when inline-headless ergonomics have been confirmed across all
 * compounds.
 */
export declare function CollapsiblePanel(props: CollapsiblePanelProps): JSX.Element;
```

