import type { JSX, ValidComponent } from "@solidjs/web";
import type { NativeButtonProps } from "../../internals/types.js";
/**
 * Props for {@link CollapsibleTrigger}.
 *
 * Stage-01c rewire: this wrapper is now a structural adapter over
 * `useCollapsible()` (axes A + G + P). `render={}` is gone — use `as=`
 * to swap the underlying tag/component.
 */
export interface CollapsibleTriggerProps extends JSX.ButtonHTMLAttributes<HTMLButtonElement>, NativeButtonProps {
    /**
     * Tag/component to render. Defaults to `"button"`. Replaces the
     * pre-spike `render` prop (axis G).
     */
    as?: ValidComponent;
    /**
     * Whether the trigger is disabled. Falls back to the collapsible's own
     * disabled state when not specified.
     */
    disabled?: boolean | undefined;
}
/**
 * A button that opens and closes the collapsible panel. Renders a `<button>`
 * element (or `as` override).
 *
 * Solid 2 notes:
 *
 * - Reads the collapsible API via `useCollapsible()` — works both under
 *   `<Collapsible.Root>` (which provides the new `CollapsibleContext`) and
 *   inside accordion items (which bridge both contexts).
 * - `useButton` provides keyboard activation (Space/Enter) and
 *   disabled-suppression via `event.preventDefault()`. Composed via
 *   `mergeRootProps(buttonProps, c.trigger(userProps))`: `buttonProps` is
 *   the "internal" side (runs first), `c.trigger(userProps)` is the "user"
 *   side. This ordering ensures `useButton`'s disabled check fires before the
 *   toggle onClick. When disabled, `useButton.onClick` calls `preventDefault()`
 *   which gates the `mergeRootProps` chain and stops the toggle from running.
 * - All keys from both sides use plain-object getters (not a Proxy), so every
 *   key is always in `ownKeys` regardless of its current value. This avoids the
 *   Solid 2 undefined-attr tracking footgun: `data-panel-open` is in `ownKeys`
 *   even when closed (returning `undefined`) so the reactive binding is
 *   established on first spread.
 * - `aria-expanded` emits the literal `"true"`/`"false"` string (not a raw
 *   boolean) because RFC 07's enumerated-pseudo-boolean rules collapse raw
 *   `true` to a presence-only attribute, and screen readers expect the string.
 * - `aria-controls` is gated on `open` (matching React's `open ? panelId :
 *   undefined`) — the getter returns `undefined` while closed, so the attribute
 *   is omitted rather than dangling at a panel that isn't in the DOM (notably
 *   under SSR). `mergeRootProps` keeps the key reactive across spreads even when
 *   it starts `undefined`, so the old `""`-seed undefined-attr workaround is no
 *   longer needed (see `create-collapsible.tsx`).
 */
export declare function CollapsibleTrigger(props: CollapsibleTriggerProps): JSX.Element;
```


