export type ComboboxChangeReason = "item-press" | "clear-press" | "input-change" | "escape-key" | "outside-press" | "imperative";
export interface CreateComboboxOptions<Value = unknown> {
    /**
     * Current selected value. Consumer-owned signal. Writes happen via
     * `onValueChange` — the primitive does NOT keep an internal copy.
     */
    value: MaybeAccessor<Value | Value[] | null | undefined>;
    onValueChange?: (value: Value | Value[] | null, reason: ComboboxChangeReason) => void;
    /**
     * Current input text. Consumer-owned signal. When omitted, a computed
     * default derives the display text from the selected value's label in
     * single-select mode.
