import type { JSX } from "@solidjs/web";
/**
 * `createContextMenu` — headless primitive for the ContextMenu compound.
 *
 * ContextMenu is a thin façade over `<Menu.Root>` that:
 *  - Owns an `anchor` signal (virtual element at the right-click point).
 *  - Owns the open state per Base UI's controlled/uncontrolled contract:
 *    the gesture (right-click / long-press) writes the internal signal,
 *    seeded once from `defaultOpen`; a defined `open` option wins.
 *  - Exposes `setAnchor` + `setOpen` so `<ContextMenu.Trigger>` can update
 *    both atomically on contextmenu / pointerdown events.
 *
