import type { JSX } from "@solidjs/web";
import { type Accessor } from "solid-js";
import { type MaybeAccessor } from "../internals/maybe-accessor.js";
/**
 * Why the dialog's open state changed.
 *
 * - `"trigger-press"` — trigger was clicked or keyboard-activated.
 * - `"escape-key"` — Escape dismissed the dialog.
 * - `"outside-press"` — pointer pressed outside (when enabled).
 * - `"close-button"` — `<Dialog.Close>` was pressed.
 * - `"imperative"` — `d.setOpen()` called programmatically.
 */
export type DialogChangeReason = "trigger-press" | "escape-key" | "outside-press" | "close-button" | "imperative";
import type { DialogModalKind } from "./dialog-root-context.js";
export type { DialogModalKind };
/**
 * Options for {@link createDialog}.
 */
export interface CreateDialogOptions {
    /**
     * Open state. Consumer-owned signal.
     */
    open: MaybeAccessor<boolean>;
    /**
     * Whether interaction is suppressed.
     * @default false
     */
    disabled?: MaybeAccessor<boolean>;
    /**
     * Modal surface kind.
     * @default true
     */
    modal?: MaybeAccessor<DialogModalKind>;
    /**
     * When true, outside-press dismissal is disabled.
     * @default false
     */
    disablePointerDismissal?: MaybeAccessor<boolean>;
    /**
     * Pre-change callback fired via `runWithOwner(null, ...)`.
     */
    onOpenChange?: (open: boolean, event: Event, reason: DialogChangeReason) => void;
}
/**
 * Public API returned by {@link createDialog}.
 */
export interface DialogApi {
    /** Reactive accessor for the current open state. */
    open: Accessor<boolean>;
    /** Whether interaction is suppressed. */
    disabled: Accessor<boolean>;
    /** Modal surface kind. */
    modal: Accessor<DialogModalKind>;
    /** Whether outside-press dismissal is disabled. */
    disablePointerDismissal: Accessor<boolean>;
    /** Imperative open setter. */
    setOpen: (next: boolean, event?: Event, reason?: DialogChangeReason) => void;
    /** Flip open (no-op when disabled). */
    toggle: (event?: Event, reason?: DialogChangeReason) => void;
    /** Context provider. */
    Provider: (props: {
        children: JSX.Element;
    }) => JSX.Element;
}
