import type { JSX } from "@solidjs/web";
import { type Accessor } from "solid-js";
import { type FieldRegistration, type FieldValidateFn, type FieldValidationMode, type FieldValidationProps, type FieldValidityData, type MutableRef } from "../internals/field-context.js";
import { type MaybeAccessor } from "../internals/maybe-accessor.js";
/**
 * Why a value/touched/lifecycle change happened. Emitted as the third
 * argument of `onValueChange(next, event, reason)` and accepted by
 * imperative setters.
 *
 * - `"input"` — change originated from the control's `onInput` handler.
 * - `"reset"` — change originated from {@link FieldApi.reset}.
 * - `"imperative"` — programmatic change with no originating DOM event,
 *   or caller-supplied reason not covered above.
 */
export type FieldChangeReason = "input" | "reset" | "imperative";
/**
 * Options for {@link createField}.
 *
 * Everything reactive accepts `MaybeAccessor<T>` so a consumer can flip
 * `disabled`/`invalid`/`name` etc. at runtime without re-creating the
 * primitive.
 */
export interface CreateFieldOptions<V = unknown> {
    /**
     * Value accessor. Consumer-owned signal — `createField` reads through
     * this and never owns its own value state. The setup-time read is
     * captured and used as the reset target (`reset()` fires
     * `onValueChange(initial, event, "reset")` so the consumer can
     * restore their signal). See `solidify.md` §6.
     */
    value?: MaybeAccessor<V | undefined>;
    /**
     * Pre-change callback. Called synchronously before the internal value
     * write. The consumer may call `event.preventDefault()` to veto the
     * change.
     *
     * **Pre/post asymmetry — important.** Reading `c.value()` inside this
     * handler returns the OLD value. For post-change observation, use
     * `createEffect(c.value, (next) => ...)`.
     */
    onValueChange?: (value: V, event: Event, reason: FieldChangeReason) => void;
    /** Whether interaction is suppressed. */
    disabled?: MaybeAccessor<boolean | undefined>;
    /**
     * Force `valid: false` regardless of validator output. Useful when
     * field validity is owned by an external system (server response,
     * separate model layer).
     */
    invalid?: MaybeAccessor<boolean | undefined>;
    /**
     * External `dirty` override. When defined, `c.dirty()` reads this
     * instead of the internal flip-flop. Setter calls become no-ops
     * (consumer is the source of truth).
     */
    dirty?: MaybeAccessor<boolean | undefined>;
    /** External `touched` override. Same shape as {@link dirty}. */
    touched?: MaybeAccessor<boolean | undefined>;
    /**
     * Identifier this field uses when registering into a surrounding
     * `<Form>`. Optional — when omitted, the field still validates but
     * isn't keyed into the form's `fields` map by name (server-error
     * lookup uses this name; cross-field `formValues` keys by it).
     */
    name?: MaybeAccessor<string | undefined>;
    /**
     * Custom validator. Receives the current value and a snapshot of all
     * sibling field values keyed by name. Return a string / list of
     * strings (errors) or `null` (valid). Both sync and `async` shapes
     * are supported — `async` validators (`zod.parseAsync`, async
     * refinements, server-side checks) are awaited by the surrounding
     * `<Form>` on submit before validity is read.
     */
    validate?: FieldValidateFn;
    /**
     * When validation should run. Inherited from `<Form validationMode>`
     * if undefined.
     *
     * - `"onSubmit"` — only on form submit (default after a failed submit
     *   triggers re-validation on every change).
     * - `"onBlur"` — when the control loses focus.
     * - `"onChange"` — every input event (with optional debounce).
     */
    validationMode?: MaybeAccessor<FieldValidationMode | undefined>;
    /** Debounce for `validationMode === "onChange"` (ms). */
    validationDebounceTime?: MaybeAccessor<number | undefined>;
}
/**
 * Public API returned by {@link createField}. Flat accessors at the root —
 * no `state` blob.
 *
 * The `[SNAPSHOT_KEYS]` symbol is attached post-construction (NOT declared
 * on this interface; see `primitive-template.md` §2.5) so `snapshot(c)`
 * returns a debug-friendly plain-object view of the field's logical state.
 */
export interface FieldApi<V = unknown> {
    /** Current value (controlled accessor wins; falls back to internal). */
    value: Accessor<V | undefined>;
    /**
     * Imperative value setter. Fires `onValueChange(next, event, reason)`
     * before the internal write; consumer can `event.preventDefault()` to
     * veto.
     */
    setValue: (next: V, event?: Event, reason?: FieldChangeReason) => void;
    /** Whether interaction is suppressed. */
    disabled: Accessor<boolean>;
    /** External-invalid override or form-level error presence. */
    invalid: Accessor<boolean>;
    /** Whether the user has typed/cleared since mount. */
    dirty: Accessor<boolean>;
    /** Whether the control has lost focus at least once. */
    touched: Accessor<boolean>;
    /** Whether the input element currently has a non-empty value. */
    filled: Accessor<boolean>;
    /** Whether the input element currently has focus. */
    focused: Accessor<boolean>;
    setDirty: (value: boolean) => void;
    setTouched: (value: boolean) => void;
    setFilled: (value: boolean) => void;
    setFocused: (value: boolean) => void;
    /** Raw validity record (state + errors + value snapshot). */
    validity: Accessor<FieldValidityData>;
    /**
     * Tri-state: `true` (passed all checks), `false` (custom or native
     * error), `null` (not yet validated).
     */
    valid: Accessor<boolean | null>;
    /** True while an async `validate` is in-flight. */
    validating: Accessor<boolean>;
    /** Active error messages from the last validation. */
    errors: Accessor<readonly string[]>;
    /**
     * First / primary error, if any. Convenience for the common
     * single-error rendering case.
     */
    error: Accessor<string>;
    /**
     * Imperatively validate the current value. Returns the in-flight
     * Promise when `options.validate` is `async` (so callers can `await`);
     * returns `void` when the validator is sync (writes have already
     * landed). The surrounding `<Form>`'s submit path uses the same
     * shape to gate submission on async validators.
     */
    validate: (event?: Event) => Promise<void> | void;
    /**
     * Restore the value to the setup-time captured initial, clear
     * touched/dirty/validity. Fires `onValueChange(initial, event,
     * "reset")` with the synthesized event so consumers can observe (and
     * optionally veto).
     */
    reset: (event?: Event) => void;
    /**
     * Control slot — getter-bag of HTML attributes ready for spreading
     * onto an `<input>` (or any compatible element). Includes the
     * validation pipeline's `onInput` handler, `aria-invalid`, focus/blur
     * handlers, and the registered control id.
     */
    control: <U extends object | undefined = undefined>(userProps?: U) => FieldControlSlotProps & (U extends object ? U : object);
    /** Directive form of {@link control}. */
    controlRef: () => (el: HTMLInputElement | null) => void;
    /**
     * Context provider. Wrap a subtree to make this api discoverable via
     * {@link useField} without prop-drilling.
     */
    Provider: (props: {
        children: JSX.Element;
    }) => JSX.Element;
    /**
     * Internal bridge surface for `<Field.Root>` composition. Not part of
     * the public API — see {@link FieldApiInternal}.
     */
    _internal: FieldApiInternal<V>;
