import { type Accessor } from "solid-js";
import { type FieldRootState } from "../internals/field-context.js";
import { type MaybeAccessor } from "../internals/maybe-accessor.js";
/** State surface exposed to slot consumers. Mirrors the surrounding field. */
export interface InputState extends FieldRootState {
}
/**
 * Options for {@link createInput}. Every reactive input is `MaybeAccessor<T>`
 * — pass an accessor to make the value reactive (or a bare value; Solid's
 * JSX-proxy makes wrapper props reactive either way, and `readOption` is
 * identity on non-functions).
 *
 * **Solid-native shape.** Like the other field controls, `createInput` owns
 * no value/validation state of its own — that lives in the surrounding
 * `<Field.Root>`. The primitive reads the field/labelable/messages contexts
 * internally and projects a control prop-bag. Outside a `<Field.Root>` every
 * context resolves to its NOOP form and the control still renders a plain
 * `<input>`.
 */
export interface CreateInputOptions {
    /**
     * The control's live value. Used for field-control registration and to
     * drive the surrounding field's `filled` state. Not written back onto the
     * element by the primitive — spread it (or pass it through `control()`'s
     * `userProps`) yourself.
     */
    value?: MaybeAccessor<string | number | readonly string[] | undefined>;
    /**
     * Whether the control is disabled. Composed with the field's `disabled`
     * (either being true disables the control).
     * @default false
     */
    disabled?: MaybeAccessor<boolean | undefined>;
    /**
     * Explicit id for the control. Read once during setup (matches
     * `useBaseUiId`'s stable-id semantics); generated when omitted.
     */
    id?: string | undefined;
    /** Form-submission name. Falls back to the field's `name`. */
    name?: MaybeAccessor<string | undefined>;
}
/** Shape of attributes emitted by `c.control()`. */
export interface InputControlSlotProps {
    id: string;
    disabled: boolean;
    name: string | undefined;
    "aria-labelledby": string;
    "aria-describedby": string;
    "data-disabled": "" | undefined;
    onFocus: (event: FocusEvent) => void;
    onBlur: (event: FocusEvent & {
        currentTarget: HTMLInputElement;
    }) => void;
    onInput: (event: InputEvent & {
        currentTarget: HTMLInputElement;
    }) => void;
    onKeyDown: (event: KeyboardEvent & {
        currentTarget: HTMLInputElement;
    }) => void;
}
/**
 * Public API returned by {@link createInput}. Flat accessors at the root; the
 * control prop-bag (`control`) and its directive form (`controlRef`) carry the
 * field wiring. No `Provider`/`useInput` — an `<input>` is a leaf with no
 * descendant subtree that would read the api back (same call as Toggle's
 * skipped provider).
 */
export interface InputApi {
    /** Composed `disabled` (field's OR the option's). */
    disabled: Accessor<boolean>;
    /** The field-derived state (field state + composed `disabled`). */
    state: Accessor<InputState>;
    /** The resolved control id. Stable for the primitive's lifetime. */
    id: string;
    /**
     * Control slot — getter-bag of attributes + handlers ready for spreading
     * onto a native `<input>`. Does NOT include `ref`; bind the element via
     * {@link bindControl} (or use {@link controlRef} for the directive form).
     */
    control: <U extends object | undefined = undefined>(userProps?: U) => InputControlSlotProps & (U extends object ? U : object);
    /**
     * Plain setter that binds the live `<input>` element into the field's
     * validation pipeline (`element.validity` reads, `setCustomValidity`
     * writes). Compose with the consumer's ref via `composeRefs`. Use this
     * when the element already receives `control()`'s prop bag via spread.
     */
    bindControl: (el: HTMLInputElement | null) => void;
    /**
     * Directive form — a `ref` callback that spreads the control bag onto the
     * element AND binds it into the validation pipeline. For cva-style
     * consumers that own the element's prop surface and don't spread
     * `control()`.
     */
    controlRef: () => (el: HTMLInputElement | null) => void;
}
/**
 * Solid 2.0-native field-control primitive for a native `<input>` that
 * integrates with a surrounding `<Field.Root>`. Wires (when inside a field):
 *
 *   - id registration into the labelable provider so `<Field.Label>`'s
 *     `htmlFor` can target this input.
 *   - value registration into the field (and any `<Form>` above) via
 *     `useFieldControlValidation`.
 *   - `aria-labelledby` composed from registered labels.
 *   - `aria-describedby` composed from `<Field.Description>` / `<Field.Error>`
 *     ids via the field-messages registry.
 *   - `aria-invalid` — flipped to literal `"true"` once validation latches
 *     invalid (via `getInputValidationProps()`).
 *   - `onInput` / `onBlur` / `onFocus` / `onKeyDown` into the field's
 *     touched / dirty / filled / focused setters and the validation pipeline.
 *
 * Must be called in an owner scope (component body or `createRoot`) — it
 * reads contexts and installs effects / cleanups.
 */
export declare function createInput(options?: CreateInputOptions): InputApi;
```

