import { type Accessor } from "solid-js";
import type { FieldRootState } from "../internals/field-constants.js";
/**
 * The full state shape exposed by `<Radio.Root>` to its children. Mirrors
 * React's `RadioRootState` (see
 * `packages/react/src/radio/root/RadioRoot.tsx` — the inline `RadioRootState`
 * interface extends `FieldRootState`).
 *
 * `checked`, `disabled`, `readOnly` and `required` are the radio-specific
 * slots. The remainder (`valid`, `touched`, `dirty`, `filled`, `focused`) are
 * inherited from the surrounding `<Field.Root>` when one exists — they flow
 * through `data-*` projection and the `render` / `class` / `style` callbacks.
 */
export interface RadioRootState extends FieldRootState {
    /** Whether the radio button is currently selected. */
    checked: boolean;
    /** Whether the component should ignore user interaction. */
    disabled: boolean;
    /** Whether the user should be unable to select the radio button. */
    readOnly: boolean;
    /** Whether the user must choose a value before submitting a form. */
    required: boolean;
}
/**
 * The context value consumed by `<Radio.Indicator>`. Every reactive slot is
 * exposed as an `Accessor<T>` so descendants pull the latest value on demand
 * and don't trip the top-level reactive read rule (RFC 01).
 *
 * Shape diverges from the React port: React stores a plain object + dispatches
 * via re-render. Solid's no-top-level-reactive-reads rule means we need a
 * live accessor for each field so `<Radio.Indicator>`'s render body (which
 * reads `checked` inside JSX to decide whether to emit the span) stays
 * reactive without a memo ping-pong.
 */
export interface RadioRootContextValue {
    /** Accessor for the full state object (used for `data-*` projection). */
    state: Accessor<RadioRootState>;
    /** Direct accessor for `checked` — convenience for the indicator's gate. */
    checked: Accessor<boolean>;
}
