import { type Accessor } from "solid-js";
import type { BaseUIChangeEventDetails, REASONS } from "../internals/change-event-details.js";
import type { FieldRootState } from "../internals/field-constants.js";
/**
 * Reason string attached to every `onValueChange` event details object.
 * Matches Base UI React's `RadioGroup.ChangeEventReason`.
 */
export type RadioGroupChangeEventReason = typeof REASONS.none;
/**
 * Shape of the details bag handed to `onValueChange`. The consumer may call
 * `details.cancel()` on the uncontrolled branch to veto the internal write.
 */
export type RadioGroupChangeEventDetails = BaseUIChangeEventDetails<RadioGroupChangeEventReason>;
/**
 * State exposed by `<RadioGroup>`. Inherits the surrounding `<Field.Root>`
 * state so the shared `data-valid` / `data-touched` / `data-dirty` /
 * `data-filled` / `data-focused` / `data-invalid` projection flows through.
 */
export interface RadioGroupState extends FieldRootState {
    /** Whether the user should be unable to change the selected radio. */
    readOnly: boolean;
    /** Whether the user must choose a radio before submitting a form. */
    required: boolean;
}
/**
 * Context value consumed by child `<Radio.Root>` elements. Every reactive
 * slot is exposed as an `Accessor<T>` so descendants pull the latest value
 * on demand — keeps Solid 2's no-top-level-reactive-reads rule (RFC 01)
 * satisfied.
 *
 * Shape diverges from the React port: React stores a plain object + triggers
 * re-renders; Solid needs live accessors per slot so child radios stay
 * reactive without a memo ping-pong.
 */
export interface RadioGroupContextValue {
    /** Currently selected value — `undefined` when nothing is selected. */
    checkedValue: Accessor<unknown>;
    /**
     * Request a change to the selected value. Fires the consumer's
     * `onValueChange` (with a cancel-capable details bag) then — if not
     * canceled — writes the internal signal in the uncontrolled branch.
     */
    setCheckedValue: (value: unknown, eventDetails: RadioGroupChangeEventDetails) => void;
    /** Whether user interaction with the group is disabled. */
    disabled: Accessor<boolean>;
    /** Whether the group rejects user-driven selection changes. */
    readOnly: Accessor<boolean>;
    /** Whether the user must select a radio before submitting. */
    required: Accessor<boolean>;
    /** `name` applied to every child radio's hidden input. */
    name: Accessor<string | undefined>;
    /** Shared `form` attribute applied to every child radio's hidden input. */
    form: Accessor<string | undefined>;
    /**
     * Latched by the group's capturing `onKeyDown` whenever the user presses
     * an arrow key, and read by a focused radio's `onFocus` handler so the
     * radio can auto-select on arrow-key navigation (mirrors React's
     * `touched` / `setTouched` dance in `RadioGroup.tsx:176`).
     */
    touched: Accessor<boolean>;
    /** Flip the `touched` latch. Consumers call `setTouched(false)` after
     * acting on a touched-focus to disarm it. */
    setTouched: (next: boolean) => void;
    /** Marker — `true` when this context was provided by a real `<RadioGroup>`. */
    readonly present: boolean;
}
/**
 * Sentinel returned when a `<Radio.Root>` renders outside a `<RadioGroup>`.
 * Every setter is a no-op and every accessor returns "nothing". Callers
 * branch on `.present` to decide whether to fall back to their standalone
 * path (e.g. the radio's own consumer-owned signal for checked state).
 */
export declare const NOOP_RADIO_GROUP_CONTEXT: RadioGroupContextValue;
/**
 * Context carrying the current `<RadioGroup>` state. Provided via Solid 2's
 * context-as-provider pattern (`<RadioGroupContext value={...}>`).
 */
export declare const RadioGroupContext: import("solid-js").Context<RadioGroupContextValue>;
/**
 * Read the nearest `<RadioGroup>` context. Returns {@link NOOP_RADIO_GROUP_CONTEXT}
 * when there is no group ancestor — callers can branch on `.present` to
 * decide between "group owns the state" and standalone fallback paths.
 */
export declare function useRadioGroupContext(): RadioGroupContextValue;
```

