import { type MaybeAccessor } from "../internals/maybe-accessor.js";
import type { BaseUIComponentProps } from "../internals/types.js";
import { type RadioGroupChangeEventDetails, type RadioGroupChangeEventReason, type RadioGroupState } from "./radio-group-context.js";
export type { RadioGroupChangeEventDetails, RadioGroupChangeEventReason, RadioGroupState, };
export interface RadioGroupProps<Value = unknown> extends Omit<BaseUIComponentProps<"div", RadioGroupState>, "value"> {
    /**
     * Tag/component to render. Defaults to `"div"`. Replaces the
     * pre-spike `render` prop (axis G).
     */
    as?: ValidComponent;
    /** @default false */
    disabled?: MaybeAccessor<boolean | undefined>;
    /** @default false */
    readOnly?: MaybeAccessor<boolean | undefined>;
    /** @default false */
    required?: MaybeAccessor<boolean | undefined>;
    name?: string | undefined;
    form?: string | undefined;
    /**
     * Controlled selected value. When provided (resolved value not
     * `undefined`), the consumer owns the state — pair with
     * {@link onValueChange}; use `null` for a controlled "nothing selected"
     * state. When omitted, the group manages its own value (seeded from
     * {@link defaultValue}).
     */
    value?: MaybeAccessor<Value | undefined>;
    /**
     * Initial selected value when uncontrolled. Read once at mount.
     * @default undefined
