export interface SwitchRootProps extends NativeButtonProps, Omit<BaseUIComponentProps<"button", SwitchRootState>, "onChange"> {
    /**
     * Tag/component to render. Defaults to `"button"`. Replaces the
     * pre-spike `render` prop (axis G).
