    value?: string | undefined;
    uncheckedValue?: string | undefined;
}
export type { SwitchRootState };
/**
 * Represents the switch itself. Renders a `<button role="switch">` (or
 * `as` override) and a visually-hidden `<input type="checkbox">` for form
