    /** Tag/component to render. Defaults to `"div"`. */
    as?: ValidComponent;
    /**
     * Controlled selected tab. When provided (resolved value not
     * `undefined` — `null` counts as controlled and means "nothing
     * selected"), the consumer owns the state — pair with
     * {@link onValueChange}. When omitted, the tabs manage their own
     * selection (seeded from {@link defaultValue}).
     */
    value?: MaybeAccessor<Value | undefined>;
