import { type Accessor } from "solid-js";
import type { BaseUIChangeEventDetails, BaseUIEventReasons } from "../internals/change-event-details.js";
import type { Orientation } from "../internals/types.js";
/**
 * Change-event details handed to `setGroupValue` by child `<Toggle>` elements.
 * Mirrors `ToggleGroup.ChangeEventDetails` from the React port.
 */
export type ToggleGroupChangeEventDetails = BaseUIChangeEventDetails<BaseUIEventReasons["none"]>;
/**
 * The value handed down by `<ToggleGroup>` to descendant `<Toggle>` elements.
 *
 * Solid 2 adaptations from Base UI React's `ToggleGroupContext`:
 *
 * - Reactive slots (`value`, `disabled`) are `Accessor<T>` so toggles pull on
 *   demand without tripping the top-level-reactive-read rule (RFC 01).
 * - `setGroupValue` is wrapped in `createStableCallback` by the group root so
 *   toggles can capture it into closures without re-wiring across renders.
 * - `orientation` is a plain value (not an accessor) — it feeds both the
 *   composite root's keyboard dispatcher and the data-orientation projection,
 *   and changing it mid-lifetime is not supported by Base UI React either.
 * - `present` is true when a real `<ToggleGroup>` is an ancestor; child
 *   toggles branch on it to decide whether to override their own
 *   `pressed`/`onPressedChange` behaviour.
 */
export interface ToggleGroupContextValue<Value extends string = string> {
    /**
     * Current group value — always an array. Single-select groups carry at
     * most one entry; multi-select carries any subset.
