     * `value` string, its `nextPressed` flag (so the group can branch on
     * single vs. multi select), and the change-event details. Dispatches
     * `onValueChange(next, details)` and honours `details.cancel()`.
     */
    setGroupValue: (newValue: Value, nextPressed: boolean, details: ToggleGroupChangeEventDetails) => void;
    /** Whether the group is disabled — propagates to every child toggle. */
    disabled: Accessor<boolean>;
    /** Navigation orientation. */
    orientation: Orientation;
    /** When `true` the group allows multiple toggles to be pressed at once. */
    multiple: Accessor<boolean>;
    /**
     * Whether the group's `value` / `defaultValue` was initialized. Children
     * use this to detect the "toggle with no value inside an initialized
     * group" dev-mode error path (matches React).
     */
    isValueInitialized: Accessor<boolean>;
    /** Marker — `true` when provided by a real `<ToggleGroup>`. */
    readonly present: boolean;
}
