import type { JSX } from "@solidjs/web";
import { type Accessor } from "solid-js";
import { type MaybeAccessor } from "../internals/maybe-accessor.js";
/**
 * Why the tooltip's open state changed.
 *
 * - `"trigger-hover"` — pointer entered / left the trigger.
 * - `"trigger-focus"` — keyboard focus moved to / from the trigger.
 * - `"trigger-press"` — trigger was pressed (click / Enter / Space).
 * - `"escape-key"` — Escape dismissed the tooltip.
 * - `"outside-press"` — pointer pressed outside.
 * - `"imperative"` — `t.setOpen()` called programmatically.
 */
export type TooltipChangeReason = "trigger-hover" | "trigger-focus" | "trigger-press" | "escape-key" | "outside-press" | "imperative";
/**
 * Options for {@link createTooltip}.
 */
export interface CreateTooltipOptions {
    /**
     * Open state. Consumer-owned signal — the primitive reads through the
     * accessor and does NOT keep an internal copy.
     */
    open: MaybeAccessor<boolean>;
    /**
     * Whether interaction is suppressed.
     * @default false
     */
    disabled?: MaybeAccessor<boolean>;
    /**
     * Pre-change callback. Fired via `runWithOwner(null, ...)` to escape the
     * reactive owner.
     */
    onOpenChange?: (open: boolean, event: Event, reason: TooltipChangeReason) => void;
    /**
     * Axis on which to track the cursor position. `"none"` anchors to the
     * trigger's bounding box.
     * @default "none"
     */
    trackCursorAxis?: MaybeAccessor<"none" | "x" | "y" | "both">;
    /**
     * When true, the hover-intent `safePolygon` is NOT installed so any
     * cursor movement off the trigger closes the tooltip immediately.
     * @default false
     */
    disableHoverablePopup?: MaybeAccessor<boolean>;
    /**
     * Delay before opening (ms).
     * @default 600
     */
    delay?: MaybeAccessor<number>;
    /**
     * Delay before closing on hover-out (ms).
     * @default 300
     */
    closeDelay?: MaybeAccessor<number>;
}
/**
 * Public API returned by {@link createTooltip}.
 */
export interface TooltipApi {
    /** Reactive accessor for the current open state. */
    open: Accessor<boolean>;
    /** Whether interaction is suppressed. */
    disabled: Accessor<boolean>;
    /** Axis on which cursor tracking is applied. */
    trackCursorAxis: Accessor<"none" | "x" | "y" | "both">;
    /** Whether the hoverable-popup safe-polygon is disabled. */
    disableHoverablePopup: Accessor<boolean>;
    /** Open delay in ms. */
    delay: Accessor<number>;
    /** Close delay in ms. */
    closeDelay: Accessor<number>;
    /** Imperative open setter. */
    setOpen: (next: boolean, event?: Event, reason?: TooltipChangeReason) => void;
    /** Flip open (no-op when disabled). */
    toggle: (event?: Event, reason?: TooltipChangeReason) => void;
    /** Context provider. */
    Provider: (props: {
        children: JSX.Element;
    }) => JSX.Element;
}
/**
 * Read the nearest {@link TooltipApi} provided by `t.Provider`. Throws if
 * used outside a Provider unless `optional` is true.
 */
export declare function useTooltip(): TooltipApi;
export declare function useTooltip(optional: true): TooltipApi | null;
/**
 * Headless primitive for a tooltip compound. Owns logical state — open,
 * disabled, cursor-tracking knobs, hover delays. DOM machinery (floating-ui
 * positioning, portal, animation) lives in `<Tooltip.Root>` which composes
 * this primitive.
 */
export declare function createTooltip(options: CreateTooltipOptions): TooltipApi;
```

